const paths={users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M16 3a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',trophy:'M8 3h8v5a4 4 0 0 1-8 0V3 M8 5H4v2a4 4 0 0 0 4 4 M16 5h4v2a4 4 0 0 1-4 4 M12 12v6 M8 21h8 M9 18h6v3',shield:'M12 3 3 7v5c0 5 9 9 9 9s9-4 9-9V7l-9-4 M9 10l6 6 M15 10l-6 6',chart:'M3 21h18 M5 17V11h3v6 M11 17V7h3v10 M17 17V3h3v14',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',bookmark:'M5 3h14v18l-7-4-7 4V3',swords:'M4 3l17 17 M3 4l4 1-2 2-1-4 M20 3 3 20 M17 5l4-1-1 4 M16 20l4-4 M4 16l4 4'};
function icon(name){return `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.shield}"/></svg>`}document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));
const baseGuilds=[{id:'unisat',name:'UniSat',tier:'Legend',level:8,volume:6.48,members:892,capacity:1000,activity:96,policy:'open',description:'Big ambition. Shared conviction. A community for traders who think ahead.',style:'High-volume · All markets'},{id:'stellar',name:'Stellar Syndicate',tier:'Diamond',level:7,volume:4.97,members:768,capacity:800,activity:92,policy:'approval',description:'A measured approach to the markets. Built for analytical minds and long-term growth.',style:'Quantitative · BTC & ETH'},{id:'alpha',name:'Alpha Hunters',tier:'Diamond',level:7,volume:4.19,members:699,capacity:800,activity:89,policy:'open',description:'Find the signal. Share the edge. A focused squad exploring the next opportunity.',style:'Active trading · All markets'},{id:'chain',name:'Chain Raiders',tier:'Platinum',level:6,volume:3.26,members:620,capacity:800,activity:87,policy:'open',description:'Independent thinkers, one strong team. Trade ideas and grow your perspective.',style:'Community · Multi-market'},{id:'delta',name:'Delta Force',tier:'Platinum',level:6,volume:2.95,members:588,capacity:600,activity:85,policy:'approval',description:'Precision over noise. A close-knit community with a disciplined trading mindset.',style:'Risk-focused · Majors'},{id:'nova',name:'Nova Guild',tier:'Gold',level:5,volume:1.82,members:312,capacity:500,activity:82,policy:'open',description:'New perspectives. New connections. Your space to learn, contribute and level up.',style:'Learning · Open community'}];
let state={saved:[],membership:null,pending:[],drafts:[],wallet:false};try{Object.assign(state,JSON.parse(localStorage.getItem('xox-guild-demo-v1')||'{}'))}catch{}
let filter='all',query='',period='14',full=false,sortDesc=true;const $=s=>document.querySelector(s);const modal=$('#modal');const content=$('#modal-content');
const escapeHtml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const guilds=()=>[...baseGuilds,...state.drafts].map(g=>state.membership?.id===g.id&&!state.membership.created?{...g,members:g.members+1}:g);const guildById=id=>guilds().find(g=>g.id===id);const money=v=>v===0?'$0.00':v>=1?'$'+v.toFixed(2)+'B':'$'+(v*1000).toFixed(1)+'M';const emblem=g=>g.logoData||`assets/${g.logo|| (baseGuilds.some(b=>b.id===g.id)?g.id:'chain')}.webp`;const tier=g=>typeof guildRankChip==='function'?guildRankChip(g):g.isNew?'<span class="tier">New guild</span>':`<span class="tier ${g.tier.toLowerCase()}">${g.tier}</span><span class="level">Lv.${g.level}</span>`;
function save(){try{localStorage.setItem('xox-guild-demo-v1',JSON.stringify(state))}catch{}render()}
let toastTimer;function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500)}
function open(html){content.innerHTML=html;if(!modal.open)modal.showModal();content.querySelector('[autofocus]')?.focus()}
function close(){modal.close()}
$('.close').onclick=close;modal.addEventListener('click',e=>{if(e.target===modal)close()});
function renderRankings(){let arr=[...guilds()].sort((a,b)=>sortDesc?b.volume-a.volume:a.volume-b.volume);if(full)arr=[...guilds()].sort((a,b)=>sortDesc?b.volume-a.volume:a.volume-b.volume);const multiplier=period==='14'?1:period==='30'?2.17:8.62;$('#ranking-rows').innerHTML=arr.slice(0,full?arr.length:5).map(g=>{let rank=[...guilds()].sort((a,b)=>b.volume-a.volume).findIndex(x=>x.id===g.id)+1;return `<tr data-guild="${g.id}" tabindex="0" role="button" aria-label="View ${escapeHtml(g.name)}"><td><span class="rank-number rank-${rank}">${rank<4?'♜ ':''}${rank}</span></td><td><div class="guild-cell"><img class="mini-emblem" src="${emblem(g)}" alt="">${escapeHtml(g.name)}</div></td><td>${tier(g)}</td><td>${money(g.volume*multiplier)}</td><td>${Math.round(g.points??g.volume*380000).toLocaleString()}</td><td>${g.members.toLocaleString()}</td><td><span class="positive">${g.activity}% active</span></td></tr>`}).join('');$('#full-ranking').innerHTML=full?'Show top 5 <span>↑</span>':'Explore full leaderboard <span><svg class=arrow viewBox="0&#32;0&#32;20&#32;20" aria-hidden=true><path d="M5&#32;15&#32;15&#32;5M5&#32;5h10v10"/></svg></span>';$('#sort-volume').textContent=(period==='14'?'14D':period==='30'?'30D':'All-time')+' volume '+(sortDesc?'↓':'↑')}
function actionLabel(g){return state.membership?.id===g.id?'My Guild <svg class=arrow viewBox="0&#32;0&#32;20&#32;20" aria-hidden=true><path d="M5&#32;15&#32;15&#32;5M5&#32;5h10v10"/></svg>':state.pending.includes(g.id)?'Application pending':g.policy==='approval'?'View details <svg class=arrow viewBox="0&#32;0&#32;20&#32;20" aria-hidden=true><path d="M5&#32;15&#32;15&#32;5M5&#32;5h10v10"/></svg>':'Join guild <svg class=arrow viewBox="0&#32;0&#32;20&#32;20" aria-hidden=true><path d="M5&#32;15&#32;15&#32;5M5&#32;5h10v10"/></svg>'}
function renderCards(){let arr=guilds().filter(g=>(filter==='all'||filter==='saved'&&state.saved.includes(g.id)||filter===g.policy)&&g.name.toLowerCase().includes(query.toLowerCase()));$('#guild-cards').innerHTML=arr.map(g=>`<article class="guild-card"><div class="card-header"><img src="${emblem(g)}" alt=""><div><h3>${escapeHtml(g.name)}</h3>${tier(g)}</div><button class="bookmark ${state.saved.includes(g.id)?'is-saved':''}" data-save="${g.id}" aria-label="${state.saved.includes(g.id)?'Unsave':'Save'} ${escapeHtml(g.name)}" aria-pressed="${state.saved.includes(g.id)}">${icon('bookmark')}</button></div><p class="card-description">${escapeHtml(g.description)}</p><div class="card-stats"><div><small>14D TRADING VOLUME</small><strong>${money(g.volume)}</strong></div><div><small>MEMBERS</small><strong>${g.members.toLocaleString()}</strong></div></div><div class="card-bottom"><span class="policy ${g.policy}"><i></i>${g.policy==='open'?'Open to join':'Approval required'}</span><button data-guild="${g.id}">${actionLabel(g)}</button></div></article>`).join('');$('#no-results').hidden=arr.length>0;$('#guild-count').textContent=guilds().length;$('#saved-count').textContent=state.saved.length}
function render(){renderRankings();renderCards();$('#wallet-label').textContent=state.wallet?'Demo trader':'Connect wallet'}
function showGuild(id){const g=guildById(id);if(!g)return;let own=state.membership?.id===g.id,pending=state.pending.includes(g.id);open(`<div class="modal-eyebrow">GUILD PROFILE · DEMO</div><div class="detail-top"><img src="${emblem(g)}" alt=""><div><h2>${escapeHtml(g.name)}</h2>${tier(g)}</div></div><p>${escapeHtml(g.description)}</p><div class="detail-stats"><div><small>14D VOLUME</small><strong>${money(g.volume)}</strong></div><div><small>MEMBERS</small><strong>${g.members.toLocaleString()}</strong></div><div><small>ACTIVE MEMBERS</small><strong>${g.activity}%</strong></div></div><h3>Find your place in the team</h3><p>${escapeHtml(g.style||'Community · All markets')}</p><ul><li>${g.policy==='open'?'Open membership — no approval required.':'Applications are reviewed by guild leadership.'}</li><li>One active guild membership per demo profile.</li><li>No funds or transactions are involved in this demo.</li></ul>${own?'<div class="member-banner">You are a member of this guild in the demo.</div>':pending?'<div class="member-banner">Your demo application is pending review. No application has been sent to XOX.</div>':''}<div class="modal-actions"><button class="secondary" data-toggle-save="${g.id}">${state.saved.includes(g.id)?'Remove from saved':'Save guild'}</button><button class="primary" ${pending?'disabled':''} data-${own?'manage':'join'}="${g.id}">${own?'Open My Guild':pending?'Application pending':g.policy==='open'?'Join demo guild <svg class=arrow viewBox="0&#32;0&#32;20&#32;20" aria-hidden=true><path d="M5&#32;15&#32;15&#32;5M5&#32;5h10v10"/></svg>':'Apply to join <svg class=arrow viewBox="0&#32;0&#32;20&#32;20" aria-hidden=true><path d="M5&#32;15&#32;15&#32;5M5&#32;5h10v10"/></svg>'}</button></div>`)}
function showJoin(id){const g=guildById(id);if(state.membership&&state.membership.id!==id){open(`<div class="modal-eyebrow">YOUR GUILD</div><h2>You already have a team.</h2><p>You are a demo member of ${escapeHtml(guildById(state.membership.id)?.name||'a guild')}. Leave your current guild in My Guild before joining another.</p><div class="modal-actions"><button class="secondary" data-guild="${id}">Back to profile</button><button class="primary" data-action="myguild">My Guild <svg class=arrow viewBox="0&#32;0&#32;20&#32;20" aria-hidden=true><path d="M5&#32;15&#32;15&#32;5M5&#32;5h10v10"/></svg></button></div>`);return}open(`<div class="modal-eyebrow">${g.policy==='open'?'JOIN THE TEAM':'GUILD APPLICATION'} · DEMO</div><h2>${g.policy==='open'?'Your next chapter.':'Make an introduction.'}</h2><p>${g.policy==='open'?'Join':'Apply to'} <strong>${escapeHtml(g.name)}</strong> and start your guild journey.</p><form id="join-form" class="form" data-id="${id}"><label for="trader-name">Trader name</label><input id="trader-name" name="name" required maxlength="30" placeholder="How should your team know you?" value="${escapeHtml(state.membership?.name||'')}" autofocus>${g.policy==='approval'?'<label for="intro">Why this guild?</label><textarea id="intro" name="intro" rows="3" required maxlength="300" placeholder="Share a little about your trading interests…"></textarea>':''}<div class="notice">This is a browser-local demonstration. Your ${g.policy==='open'?'membership':'application'} stays on this device. No wallet signature or blockchain transaction is required.</div><div class="modal-actions"><button class="secondary" type="button" data-guild="${id}">Back</button><button class="primary" type="submit">${g.policy==='open'?'Join demo guild':'Save demo application'} <svg class=arrow viewBox="0&#32;0&#32;20&#32;20" aria-hidden=true><path d="M5&#32;15&#32;15&#32;5M5&#32;5h10v10"/></svg></button></div></form>`)}
function showCreate(){if(state.membership){showMyGuild();toast('Leave your current demo guild before creating a new one.');return}open(`<div class="modal-eyebrow">BUILD SOMETHING TOGETHER</div><h2>Start your own guild.</h2><p>A shared vision deserves a home. Set up your demo guild.</p><form id="create-form" class="form"><label for="guild-name">Guild name</label><input id="guild-name" name="name" required minlength="3" maxlength="28" placeholder="Give your team a name" autofocus><label for="guild-description">Your guild’s story</label><textarea id="guild-description" name="description" required minlength="10" maxlength="180" rows="3" placeholder="What brings your traders together?"></textarea><div class="row"><div><label for="guild-policy">Membership</label><select id="guild-policy" name="policy"><option value="open">Open to join</option><option value="approval">Approval required</option></select></div><div><label for="guild-style">Trading focus</label><select id="guild-style" name="style"><option>Community · All markets</option> <option>Quantitative · BTC & ETH</option><option>Learning · Open community</option><option>Active trading · All markets</option></select></div></div><label class="check"><input type="checkbox" required><span>I understand this creates a local demo guild, with no on-chain creation or fees.</span></label><div class="modal-actions"><button class="primary" type="submit">Create demo guild <svg class=arrow viewBox="0&#32;0&#32;20&#32;20" aria-hidden=true><path d="M5&#32;15&#32;15&#32;5M5&#32;5h10v10"/></svg></button></div></form>`)}
function showMyGuild(){const g=state.membership&&guildById(state.membership.id);if(!g){open(`<div class="modal-eyebrow">YOUR GUILD JOURNEY</div><h2>Your team is out there.</h2><p>Join a guild that shares your ambition, or bring your own trading circle together.</p>${state.pending.length?`<h3>Pending demo applications</h3><div class="activity-list">${state.pending.map(id=>`<div>${escapeHtml(guildById(id)?.name||id)}<small>Saved locally · Awaiting simulated review <button class="text-button" data-cancel="${id}">Cancel application</button></small></div>`).join('')}</div>`:''}<div class="modal-actions"><button class="secondary" data-action="discover">Find a Guild <svg class=arrow viewBox="0&#32;0&#32;20&#32;20" aria-hidden=true><path d="M5&#32;15&#32;15&#32;5M5&#32;5h10v10"/></svg></button><button class="primary" data-action="create">Create Guild ＋</button></div>`);return}open(`<div class="modal-eyebrow">MY GUILD · LOCAL DEMO</div><div class="detail-top"><img src="${emblem(g)}" alt=""><div><h2>${escapeHtml(g.name)}</h2>${tier(g)}</div></div><div class="member-banner">Welcome, ${escapeHtml(state.membership.name)}. You are the ${state.membership.role==='owner'?'founder':'newest member'} of this demo guild.</div><div class="detail-stats"><div><small>GUILD MEMBERS</small><strong>${g.members}</strong></div><div><small>YOUR VOLUME</small><strong>$0.00</strong></div><div><small>YOUR POINTS</small><strong>0</strong></div></div><h3>Your journey</h3><div class="activity-list"><div>${state.membership.created?'Founded':'Joined'} ${escapeHtml(g.name)}<small>Demo activity · Stored on this device</small></div><div>Ready for your next chapter<small>Trading and rewards require the XOX production integration.</small></div></div><div class="modal-actions"><button class="secondary" data-guild="${g.id}">Guild profile</button><button class="secondary danger" data-action="leave">Leave demo guild</button></div>`)}
function showBattle(){open(`<div class="modal-eyebrow">THE GUILD ARENA · FEATURE PREVIEW</div><h2>One team. One ambition.</h2><div class="battle-arena"><div class="contender"><img src="assets/unisat.webp" alt=""><h3>UniSat</h3></div><div class="versus">VS</div><div class="contender"><img src="assets/alpha.webp" alt=""><h3>Alpha Hunters</h3></div></div><p>A concept for guild-to-guild competition, bringing team participation and trading performance into one arena.</p><h3>The proposed experience</h3><ul><li>A dedicated matchup and team progress view.</li><li>Transparent scoring and a clear competition window.</li><li>A results view with confirmed reward details.</li></ul><div class="notice">This matchup is illustrative. There is no live battle, active reward pool or confirmed competition schedule connected to this concept.</div><div class="modal-actions"><button class="primary" data-action="discover">Explore demo guilds <svg class=arrow viewBox="0&#32;0&#32;20&#32;20" aria-hidden=true><path d="M5&#32;15&#32;15&#32;5M5&#32;5h10v10"/></svg></button></div>`)}
function showWallet(){open(`<div class="modal-eyebrow">EXPLORE XOX GUILDS</div><h2>Your guild journey starts here.</h2><p>This concept has no production wallet connection. Use a demo profile to explore the experience without a wallet or funds.</p><div class="wallet-options"><button class="primary" data-action="demo-wallet">${state.wallet?'Continue as demo trader':'Use demo profile'} <span><svg class=arrow viewBox="0&#32;0&#32;20&#32;20" aria-hidden=true><path d="M5&#32;15&#32;15&#32;5M5&#32;5h10v10"/></svg></span></button><a class="secondary" href="https://xox.exchange" target="_blank" rel="noopener">Visit XOX exchange <span><svg class=arrow viewBox="0&#32;0&#32;20&#32;20" aria-hidden=true><path d="M5&#32;15&#32;15&#32;5M5&#32;5h10v10"/></svg></span></a></div><div class="notice">Demo profiles and memberships are saved in this browser only. Real wallet authentication and guild contracts are not integrated.</div>`)}
const actions={create:showCreate,battle:showBattle,myguild:showMyGuild,wallet:showWallet,discover:()=>{close();$('#discover').scrollIntoView({behavior:'smooth'})},'demo-wallet':()=>{state.wallet=true;save();close();toast('Demo profile ready. Find your guild.')} ,leave:()=>{open(`<div class="modal-eyebrow">MY GUILD</div><h2>Leave your demo guild?</h2><p>Your local membership will be removed. You can join another demo guild at any time.</p><div class="modal-actions"><button class="secondary" data-action="myguild">Stay with my team</button><button class="secondary danger" data-action="confirm-leave">Leave guild</button></div>`)},'confirm-leave':()=>{state.membership=null;save();showMyGuild();toast('You left your demo guild.')},about:()=>open(`<div class="modal-eyebrow">ABOUT THIS EXPERIENCE</div><h2>Made for the guild journey.</h2><p>An interactive XOX Guilds concept based on the supplied design handoff. Every ranking, member count, volume and guild profile is illustrative.</p><h3>What you can explore</h3><ul><li>Search, filter and save guilds.</li><li>Compare demonstration ranking periods.</li><li>Join, apply to and create demo guilds.</li><li>Manage your local demo membership.</li></ul><div class="notice">This is a design prototype. Live data, wallet authentication, contracts, approvals, trading and rewards require production integration. No funds move through this site.</div>`) };
document.addEventListener('click',e=>{const b=e.target.closest('button,a,tr[data-guild]');if(!b)return;if(b.dataset.action){actions[b.dataset.action]?.();return}if(b.dataset.guild){showGuild(b.dataset.guild);return}if(b.dataset.join){showJoin(b.dataset.join);return}if(b.dataset.manage){showMyGuild();return}const id=b.dataset.save||b.dataset.toggleSave;if(id){state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];save();if(b.dataset.toggleSave)showGuild(id);return}if(b.dataset.cancel){state.pending=state.pending.filter(x=>x!==b.dataset.cancel);save();showMyGuild()}if(b.dataset.filter){filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('selected',x===b));renderCards()}if(b.dataset.period){period=b.dataset.period;document.querySelectorAll('[data-period]').forEach(x=>x.classList.toggle('selected',x===b));renderRankings()}});
document.addEventListener('submit',e=>{if(e.target.id==='create-form'){e.preventDefault();const f=new FormData(e.target),name=f.get('name').trim(),description=f.get('description').trim();if(name.length<3||description.length<10){toast('Add a guild name and a short story.');return}if(guilds().some(g=>g.name.toLowerCase()===name.toLowerCase())){toast('That guild name is already in use. Try another.');return}const id='guild-'+Date.now();state.drafts.push({id,name,description,policy:f.get('policy'),style:f.get('style'),tier:'Gold',level:1,volume:0,members:1,capacity:100,activity:0});state.membership={id,name:'Founder',role:'owner',created:true};state.wallet=true;save();showMyGuild();toast('Your demo guild is ready.');}if(e.target.id==='join-form'){e.preventDefault();const id=e.target.dataset.id,g=guildById(id),f=new FormData(e.target);if(!f.get('name').trim()){toast('Please enter your trader name.');return}if(g.policy==='approval'){if(!state.pending.includes(id))state.pending.push(id);save();open(`<div class="success-mark">✓</div><div class="modal-eyebrow">SAVED ON THIS DEVICE</div><h2>Your introduction is ready.</h2><p>Your demo application to ${escapeHtml(g.name)} has been saved locally. It has not been sent to XOX or a guild leader.</p><div class="modal-actions"><button class="primary" data-action="myguild">View my applications <svg class=arrow viewBox="0&#32;0&#32;20&#32;20" aria-hidden=true><path d="M5&#32;15&#32;15&#32;5M5&#32;5h10v10"/></svg></button></div>`)}else{state.membership={id,name:f.get('name').trim(),role:'member',created:false};state.wallet=true;save();showMyGuild();toast(`Welcome to ${g.name} — demo membership active.`)}}});
$('#search').addEventListener('input',e=>{query=e.target.value;renderCards()});$('#reset-search').onclick=()=>{query='';filter='all';$('#search').value='';document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('selected',x.dataset.filter==='all'));renderCards()};$('#full-ranking').onclick=()=>{full=!full;renderRankings()};$('#sort-volume').onclick=()=>{sortDesc=!sortDesc;renderRankings()};document.addEventListener('keydown',e=>{if(e.key==='/'&&!modal.open&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();$('#search').focus();$('#discover').scrollIntoView({behavior:'smooth'})}if((e.key==='Enter'||e.key===' ')&&e.target.matches('tr[data-guild]')){e.preventDefault();showGuild(e.target.dataset.guild)}});render();
